p='/app/server.py';s=open(p).read()
s=s.replace("import os,sys,json,re,sqlite3,secrets,hashlib,base64,struct,time,threading,email.parser,email.policy", "import os,sys,json,re,sqlite3,secrets,hashlib,base64,struct,time,threading,email.parser,email.policy,fcntl")
s=s.replace("DB='/var/lib/huddle/huddle.db'; FILEDIR='/var/lib/huddle/files'; os.makedirs(FILEDIR,exist_ok=True)", "DB='/var/lib/huddle/huddle.db'; LOCK='/var/lib/huddle/huddle.lock'; FILEDIR='/var/lib/huddle/files'; os.makedirs(FILEDIR,exist_ok=True)")
s=s.replace("def con():\n c=sqlite3.connect(DB,timeout=5,check_same_thread=False,isolation_level='DEFERRED'); c.row_factory=sqlite3.Row; c.execute('PRAGMA busy_timeout=5000'); return c", """class Conn:
 def __init__(self):
  self.c=sqlite3.connect(DB,timeout=30,check_same_thread=False,isolation_level='DEFERRED'); self.c.row_factory=sqlite3.Row; self.c.execute('PRAGMA busy_timeout=30000'); self.l=None
 def execute(self,*a,**k): return self.c.execute(*a,**k)
 def executescript(self,*a,**k): return self.c.executescript(*a,**k)
 def commit(self):
  self.c.commit()
  if self.l: fcntl.flock(self.l,fcntl.LOCK_UN);self.l.close();self.l=None
 def close(self):
  try:self.c.close()
  finally:
   if self.l: fcntl.flock(self.l,fcntl.LOCK_UN);self.l.close()
def con():
 return Conn()
def lockwrite(c):
 if not c.l:
  c.l=open(LOCK,'w');fcntl.flock(c.l,fcntl.LOCK_EX)
 return c""")
